class N:
    def __init__(self, d):
        self.d = d
        self.l = None
        self.r = None

def ins(t, d):
    if t is None:
        return N(d)
    if d < t.d:
        t.l = ins(t.l, d)
    else:
        t.r = ins(t.r, d)
    return t

r = None
for d in [50, 30, 70, 20, 40]:
    r = ins(r, d)

out = []
def io(t):
    if t:
        io(t.l)
        out.append(t.d)
        io(t.r)
io(r)
for v in out:
    print(v)

path = []
t = r
while t:
    path.append(t.d)
    if t.d == 40:
        break
    t = t.l if 40 < t.d else t.r
print(len(path))

